import re
import requests

def task_func(input):
    """
    Extracts an API endpoint from the input string, sends a GET request to it,
    and returns the response data in JSON format.

    Args:
        input (str): The input string containing a URL.

    Returns:
        dict: The response data in JSON format, or an error message if the URL
              is not found or the request fails.
    """
    # Regex to extract the URL starting with http or https
    url_pattern = r'https?://[^\s]+'
    match = re.search(url_pattern, input)

    if not match:
        return {"error": "No URL found in the input string."}

    # Extract the URL and strip potential trailing punctuation
    url = match.group(0).rstrip('.,!?;:')

    try:
        # Send a GET request to the extracted endpoint
        response = requests.get(url)

        # Raise an exception for HTTP errors
        response.raise_for_status()

        # Return the response as a dictionary (JSON)
        return response.json()

    except requests.exceptions.RequestException as e:
        return {"error": f"HTTP Request failed: {str(e)}"}
    except ValueError:
        return {"error": "Response content is not valid JSON."}
